  91,
  '[{"id":"q_csat_quant_1","q_en":"What is 8% of 1509?","options_en":["132.79","196.17","45.27","120.72"],"correct":3,"exp":"8% of 1509 = (8/100) × 1509 = 120.72.","subject":"CSAT","subTopic":"Percentages","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_2","q_en":"What is 12% of 701?","options_en":["92.53","84.12","49.07","119.17"],"correct":1,"exp":"12% of 701 = (12/100) × 701 = 84.12.","subject":"CSAT","subTopic":"Percentages","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_3","q_en":"What is 30% of 1585?","options_en":["523.05","554.75","396.25","475.5"],"correct":3,"exp":"30% of 1585 = (30/100) × 1585 = 475.5.","subject":"CSAT","subTopic":"Percentages","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_4","q_en":"What is 5% of 265?","options_en":["26.5","39.75","14.58","13.25"],"correct":3,"exp":"5% of 265 = (5/100) × 265 = 13.25.","subject":"CSAT","subTopic":"Percentages","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_5","q_en":"What is 35% of 1234?","options_en":["493.6","475.09","370.2","431.9"],"correct":3,"exp":"35% of 1234 = (35/100) × 1234 = 431.9.","subject":"CSAT","subTopic":"Percentages","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_6","q_en":"What is 40% of 1666?","options_en":["583.1","749.7","666.4","733.04"],"correct":2,"exp":"40% of 1666 = (40/100) × 1666 = 666.4.","subject":"CSAT","subTopic":"Percentages","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_7","q_en":"What is 15% of 1406?","options_en":["140.6","281.2","231.99","210.9"],"correct":3,"exp":"15% of 1406 = (15/100) × 1406 = 210.9.","subject":"CSAT","subTopic":"Percentages","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_8","q_en":"What is 15% of 896?","options_en":["89.6","147.84","134.4","179.2"],"correct":2,"exp":"15% of 896 = (15/100) × 896 = 134.4.","subject":"CSAT","subTopic":"Percentages","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_9","q_en":"What is 8% of 409?","options_en":["12.27","53.17","32.72","35.99"],"correct":2,"exp":"8% of 409 = (8/100) × 409 = 32.72.","subject":"CSAT","subTopic":"Percentages","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_10","q_en":"What is 18% of 1935?","options_en":["383.13","445.05","348.3","251.55"],"correct":2,"exp":"18% of 1935 = (18/100) × 1935 = 348.3.","subject":"CSAT","subTopic":"Percentages","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_11","q_en":"A quantity increases from 2596 by 10%. What is the new value?","options_en":["2336.4","3115.2","2855.6","2985.4"],"correct":2,"exp":"New value = 2596 × (1 + 10/100) = 2596 × 1.1 = 2855.6.","subject":"CSAT","subTopic":"Percentages","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_12","q_en":"A quantity increases from 2974 by 30%. What is the new value?","options_en":["4163.6","3866.2","4014.9","2081.8"],"correct":1,"exp":"New value = 2974 × (1 + 30/100) = 2974 × 1.3 = 3866.2.","subject":"CSAT","subTopic":"Percentages","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_13","q_en":"A quantity increases from 684 by 10%. What is the new value?","options_en":["615.6","752.4","786.6","820.8"],"correct":1,"exp":"New value = 684 × (1 + 10/100) = 684 × 1.1 = 752.4.","subject":"CSAT","subTopic":"Percentages","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_14","q_en":"A quantity increases from 1353 by 10%. What is the new value?","options_en":["1488.3","1217.7","1623.6","1555.95"],"correct":0,"exp":"New value = 1353 × (1 + 10/100) = 1353 × 1.1 = 1488.3.","subject":"CSAT","subTopic":"Percentages","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_15","q_en":"A quantity increases from 1894 by 20%. What is the new value?","options_en":["2367.5","2272.8","2462.2","1515.2"],"correct":1,"exp":"New value = 1894 × (1 + 20/100) = 1894 × 1.2 = 2272.8.","subject":"CSAT","subTopic":"Percentages","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_16","q_en":"A quantity increases from 1493 by 10%. What is the new value?","options_en":["1716.95","1642.3","1343.7","1791.6"],"correct":1,"exp":"New value = 1493 × (1 + 10/100) = 1493 × 1.1 = 1642.3.","subject":"CSAT","subTopic":"Percentages","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_17","q_en":"A''s income is 15% more than B''s income. By what percentage is B''s income less than A''s? (round to 2 decimals)","options_en":["16.5","13.04","15","0"],"correct":1,"exp":"Let B = 100, then A = 115. B is less than A by ((115-100)/115)×100 = 13.04%. Note: this is NOT simply 15% — that''s the increase relative to B, not the decrease relative to A.","subject":"CSAT","subTopic":"Percentages","contentType":"static","difficulty":"hard"},{"id":"q_csat_quant_18","q_en":"A''s income is 31% more than B''s income. By what percentage is B''s income less than A''s? (round to 2 decimals)","options_en":["31","34.1","0","23.66"],"correct":3,"exp":"Let B = 100, then A = 131. B is less than A by ((131-100)/131)×100 = 23.66%. Note: this is NOT simply 31% — that''s the increase relative to B, not the decrease relative to A.","subject":"CSAT","subTopic":"Percentages","contentType":"static","difficulty":"hard"},{"id":"q_csat_quant_19","q_en":"A''s income is 35% more than B''s income. By what percentage is B''s income less than A''s? (round to 2 decimals)","options_en":["38.5","25.93","35","0"],"correct":1,"exp":"Let B = 100, then A = 135. B is less than A by ((135-100)/135)×100 = 25.93%. Note: this is NOT simply 35% — that''s the increase relative to B, not the decrease relative to A.","subject":"CSAT","subTopic":"Percentages","contentType":"static","difficulty":"hard"},{"id":"q_csat_quant_20","q_en":"A''s income is 16% more than B''s income. By what percentage is B''s income less than A''s? (round to 2 decimals)","options_en":["0","16","13.79","17.6"],"correct":2,"exp":"Let B = 100, then A = 116. B is less than A by ((116-100)/116)×100 = 13.79%. Note: this is NOT simply 16% — that''s the increase relative to B, not the decrease relative to A.","subject":"CSAT","subTopic":"Percentages","contentType":"static","difficulty":"hard"},{"id":"q_csat_quant_21","q_en":"A trader buys an article for ₹1010 and sells it at a loss of 8%. What is the selling price?","options_en":["1022.12","929.2","969.6","1090.8"],"correct":1,"exp":"SP = CP × (1 - 8/100) = 1010 × 0.92 = ₹929.2.","subject":"CSAT","subTopic":"Profit & Loss","contentType":"static","difficulty":"medium"},{"id":"q_csat_quant_22","q_en":"A trader buys an article for ₹705 and sells it at a loss of 8%. What is the selling price?","options_en":["648.6","761.4","713.46","676.8"],"correct":0,"exp":"SP = CP × (1 - 8/100) = 705 × 0.92 = ₹648.6.","subject":"CSAT","subTopic":"Profit & Loss","contentType":"static","difficulty":"medium"},{"id":"q_csat_quant_23","q_en":"A trader buys an article for ₹941 and sells it at a profit of 12%. What is the selling price?","options_en":["828.08","1159.31","1053.92","997.46"],"correct":2,"exp":"SP = CP × (1 + 12/100) = 941 × 1.12 = ₹1053.92.","subject":"CSAT","subTopic":"Profit & Loss","contentType":"static","difficulty":"medium"},{"id":"q_csat_quant_24","q_en":"A trader buys an article for ₹1963 and sells it at a profit of 10%. What is the selling price?","options_en":["2159.3","2061.15","2375.23","1766.7"],"correct":0,"exp":"SP = CP × (1 + 10/100) = 1963 × 1.1 = ₹2159.3.","subject":"CSAT","subTopic":"Profit & Loss","contentType":"static","difficulty":"medium"},{"id":"q_csat_quant_25","q_en":"A trader buys an article for ₹1421 and sells it at a loss of 10%. What is the selling price?","options_en":["1278.9","1563.1","1406.79","1349.95"],"correct":0,"exp":"SP = CP × (1 - 10/100) = 1421 × 0.9 = ₹1278.9.","subject":"CSAT","subTopic":"Profit & Loss","contentType":"static","difficulty":"medium"},{"id":"q_csat_quant_26","q_en":"A trader buys an article for ₹1283 and sells it at a profit of 15%. What is the selling price?","options_en":["1379.22","1090.55","1622.99","1475.45"],"correct":3,"exp":"SP = CP × (1 + 15/100) = 1283 × 1.15 = ₹1475.45.","subject":"CSAT","subTopic":"Profit & Loss","contentType":"static","difficulty":"medium"},{"id":"q_csat_quant_27","q_en":"A trader buys an article for ₹1774 and sells it at a loss of 8%. What is the selling price?","options_en":["1703.04","1795.29","1915.92","1632.08"],"correct":3,"exp":"SP = CP × (1 - 8/100) = 1774 × 0.92 = ₹1632.08.","subject":"CSAT","subTopic":"Profit & Loss","contentType":"static","difficulty":"medium"},{"id":"q_csat_quant_28","q_en":"A trader buys an article for ₹523 and sells it at a profit of 20%. What is the selling price?","options_en":["418.4","627.6","575.3","690.36"],"correct":1,"exp":"SP = CP × (1 + 20/100) = 523 × 1.2 = ₹627.6.","subject":"CSAT","subTopic":"Profit & Loss","contentType":"static","difficulty":"medium"},{"id":"q_csat_quant_29","q_en":"An article bought for ₹1339 is sold for ₹1443. What is the profit percentage? (round to 2 decimals)","options_en":["7.21","7.77","2.77","12.77"],"correct":1,"exp":"Profit = 1443 − 1339 = ₹104. Profit% = (Profit/CP)×100 = (104/1339)×100 = 7.77%.","subject":"CSAT","subTopic":"Profit & Loss","contentType":"static","difficulty":"medium"},{"id":"q_csat_quant_30","q_en":"An article bought for ₹613 is sold for ₹854. What is the profit percentage? (round to 2 decimals)","options_en":["34.31","39.31","44.31","28.22"],"correct":1,"exp":"Profit = 854 − 613 = ₹241. Profit% = (Profit/CP)×100 = (241/613)×100 = 39.31%.","subject":"CSAT","subTopic":"Profit & Loss","contentType":"static","difficulty":"medium"},{"id":"q_csat_quant_31","q_en":"An article bought for ₹963 is sold for ₹1263. What is the profit percentage? (round to 2 decimals)","options_en":["36.15","23.75","26.15","31.15"],"correct":3,"exp":"Profit = 1263 − 963 = ₹300. Profit% = (Profit/CP)×100 = (300/963)×100 = 31.15%.","subject":"CSAT","subTopic":"Profit & Loss","contentType":"static","difficulty":"medium"},{"id":"q_csat_quant_32","q_en":"An article bought for ₹929 is sold for ₹1101. What is the profit percentage? (round to 2 decimals)","options_en":["15.62","23.51","13.51","18.51"],"correct":3,"exp":"Profit = 1101 − 929 = ₹172. Profit% = (Profit/CP)×100 = (172/929)×100 = 18.51%.","subject":"CSAT","subTopic":"Profit & Loss","contentType":"static","difficulty":"medium"},{"id":"q_csat_quant_33","q_en":"Find the simple interest on ₹1000 at 10% per annum for 2 years.","options_en":["20","240","200","300"],"correct":2,"exp":"SI = (P × R × T)/100 = (1000 × 10 × 2)/100 = ₹200.","subject":"CSAT","subTopic":"Simple & Compound Interest","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_34","q_en":"Find the simple interest on ₹4000 at 6% per annum for 4 years.","options_en":["1200","96","960","1152"],"correct":2,"exp":"SI = (P × R × T)/100 = (4000 × 6 × 4)/100 = ₹960.","subject":"CSAT","subTopic":"Simple & Compound Interest","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_35","q_en":"Find the simple interest on ₹8000 at 8% per annum for 5 years.","options_en":["3200","3839.63","3840","320"],"correct":0,"exp":"SI = (P × R × T)/100 = (8000 × 8 × 5)/100 = ₹3200.","subject":"CSAT","subTopic":"Simple & Compound Interest","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_36","q_en":"Find the simple interest on ₹1000 at 6% per annum for 3 years.","options_en":["18","216","240","180"],"correct":3,"exp":"SI = (P × R × T)/100 = (1000 × 6 × 3)/100 = ₹180.","subject":"CSAT","subTopic":"Simple & Compound Interest","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_37","q_en":"Find the simple interest on ₹4000 at 12% per annum for 3 years.","options_en":["1728","144","1440","1920"],"correct":2,"exp":"SI = (P × R × T)/100 = (4000 × 12 × 3)/100 = ₹1440.","subject":"CSAT","subTopic":"Simple & Compound Interest","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_38","q_en":"Find the simple interest on ₹8000 at 5% per annum for 3 years.","options_en":["120","1600","1440","1200"],"correct":3,"exp":"SI = (P × R × T)/100 = (8000 × 5 × 3)/100 = ₹1200.","subject":"CSAT","subTopic":"Simple & Compound Interest","contentType":"static","difficulty":"easy"},{"id":"q_csat_quant_39","q_en":"Find the compound interest on ₹1000 at 20% per annum for 2 years, compounded annually.","options_en":["440","506","728","400"],"correct":0,"exp":"CI = P×(1+R/100)^T − P = 1000×(1+20/100)^2 − 1000 = ₹440.00.","subject":"CSAT","subTopic":"Simple & Compound Interest","contentType":"static","difficulty":"medium"},{"id":"q_csat_quant_40","q_en":"Find the compound interest on ₹2000 at 20% per annum for 2 years, compounded annually.","options_en":["880","1456","1012","800"],"correct":0,"exp":"CI = P×(1+R/100)^T − P = 2000×(1+20/100)^2 − 2000 = ₹880.00.","subject":"CSAT","subTopic":"Simple & Compound Interest","contentType":"static","difficulty":"medium"},{"id":"q_csat_quant_41","q_en":"Find the compound interest on ₹2000 at 10% per annum for 2 years, compounded annually.","options_en":["400","483","420","662"],"correct":2,"exp":"CI = P×(1+R/100)^T − P = 2000×(1+10/100)^2 − 2000 = ₹420.00.","subject":"CSAT","subTopic":"Simple & Compound Interest","contentType":"static","difficulty":"medium"},{"id":"q_csat_quant_42","q_en":"Find the compound interest on ₹1000 at 20% per annum for 2 years, compounded annually.","options_en":["440","506","400","728"],"correct":0,"exp":"CI = P×(1+R/100)^T − P = 1000×(1+20/100)^2 − 1000 = ₹440.00.","subject":"CSAT","subTopic":"Simple & Compound Interest","contentType":"static","difficulty":"medium"},{"id":"q_csat_quant_43","q_en":"Find the compound interest on ₹5000 at 10% per annum for 2 years, compounded annually.","options_en":["1000","1655","1207.5","1050"],"correct":3,"exp":"CI = P×(1+R/100)^T − P = 5000×(1+10/100)^2 − 5000 = ₹1050.00.","subject":"CSAT","subTopic":"Simple & Compound Interest","contentType":"static","difficulty":"medium"},{"id":"q_csat_quant_44","q_en":"Find the average of the numbers: 61, 53, 23, 41.","options_en":["43.5","35.6","44.